contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint sendEther, uint preAdvance) public payable {
        require(sendEther == 10 ether, "must send exactly 10 ether");
        require(msg.value == sendEther, "test must be funded with the amount");

        // Use any pre-existing pastBlockTime as the before value.
        uint beforePast = c.pastBlockTime();

        require(beforePast < block.timestamp, "timestamp already advanced past stored time");

        // Make preAdvance effective without violating the fallback precondition.
        uint effectiveAdvance = preAdvance;
        if (effectiveAdvance == 0) effectiveAdvance = 1;

        bool reverted;
        try c.fallback{value: sendEther}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();

        assert(!reverted && afterPast == block.timestamp && afterPast > beforePast);
    }

    receive() external payable {}
}

