contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        uint cBalBefore = address(c).balance;

        // Advance the environment timestamp is not controllable; rely on the
        // fact that a fresh C is deployed and the very first call can set
        // pastBlockTime. If the environment already set a past value, the
        // precondition require(block.timestamp > pastBlockTime) may fail.
        // We therefore only make the call when the timestamp is strictly
        // greater than the current recorded value; otherwise we skip the
        // state-changing call and assert a trivial safety condition.
        uint recordedBefore = c.pastBlockTime();
        bool canCall = block.timestamp > recordedBefore;

        if (canCall) {
            c.fallback{value: amount}();
        }

        uint recordedAfter = c.pastBlockTime();
        uint cBalAfter = address(c).balance;

        if (!canCall) {
            // No call was made, so the state must be unchanged.
            assert(recordedAfter == recordedBefore && cBalAfter == cBalBefore);
        } else {
            assert(
                recordedAfter == block.timestamp &&
                recordedAfter > recordedBefore &&
                (
                    (block.number % 15 == 0 && cBalAfter == 0) ||
                    (block.number % 15 != 0 && cBalAfter == cBalBefore + amount)
                )
            );
        }
    }

    receive() external payable {}
}

