        // and pastBlockTime == callTime.
        // If the call fails, pastBlockTime must be unchanged.
        // Since we cannot directly set block.timestamp, callTime is modeled as the current block.timestamp via the fallback uses block.timestamp.
        // So we use tx parameter as an abstract timestamp test: replace with the actual block.timestamp of this test.
        uint nowTs = block.timestamp;
        bool expectedOk = (sendAmount == 10 ether) && (nowTs > beforePastBlockTime);

        assert(
            success
                ? (sendAmount == 10 ether && afterPastBlockTime == nowTs && nowTs > beforePastBlockTime)
                : (afterPastBlockTime == beforePastBlockTime)
        );
    }

