contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 firstTimestamp) public payable {
        // Precondition: we have enough Ether to make the first call.
        require(address(this).balance >= 10 ether);

        // Setup: establish a known pastBlockTime that is strictly less than
        // 'firstTimestamp' (which will be the block.timestamp of the call).
        uint256 pastBlockTime;
        if (firstTimestamp > 1) {
            pastBlockTime = firstTimestamp - 1;
        } else {
            pastBlockTime = 0;
        }

        // Drive the contract with the first call using the supplied amount.
        // The fallback requires exactly 10 ether, so if amount != 10 ether
        // the call will revert.  We use `c.fallback()` to call the fallback
        // function explicitly.
        bool firstReverted;
        try c.fallback{value: amount}() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // General rule: a fallback call succeeds exactly when the passed amount
        // is 10 ether and the current block timestamp is greater than the
        // previously recorded pastBlockTime.  However, our setup cannot force
        // the block.timestamp to be less than the initial pastBlockTime because
        // the constructor sets pastBlockTime to 0.  Therefore the only possible
        // failure in this test is due to a wrong amount.  After a successful
        // call, pastBlockTime must equal block.timestamp of that call (which is
        // greater than 0 and different from all later block timestamps).  Since
        // the test cannot reliably set a pastBlockTime greater than the next
        // block.timestamp, we express the rule only in terms of amount.
        //
        // Concretely: the fallback reverts iff the amount is not exactly
        // 10 ether.  We use the revert flag from the first call.  Note that
        // the call might have succeeded and set pastBlockTime, but that does
        // not affect the correctness of this rule for the first call.
        assert(firstReverted == (amount != 10 ether));
    }

    receive() external payable {}
}

