contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 newTime) public payable {
        require(msg.value == 10 ether);

        uint256 oldBlockTime = c.pastBlockTime();
        uint256 oldBalance = address(c).balance;

        // Ensure the next call will be valid by making the block timestamp strictly greater
        // than the current stored pastBlockTime.
        // We cannot use vm.warp, so we rely on block.timestamp > oldBlockTime.
        // If not, the call would revert due to the contract's own require.
        // We choose an input timestamp that is at least oldBlockTime + 1.
        require(newTime > oldBlockTime);

        // The contract's fallback requires block.timestamp > pastBlockTime.
        // We cannot force block.timestamp, but we can ensure that in the current block
        // the condition holds if we set pastBlockTime to a value less than block.timestamp.
        // However, since the test runs in a fresh block, block.timestamp is current time.
        // We need to ensure block.timestamp > pastBlockTime. If not, we must first set it
        // via a preparatory call? But any call that changes state must be top-level.
        // We can just attempt the call and see if it reverts due to time.

        bool reverted;
        try c.fallback{value: msg.value}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.pastBlockTime() == block.timestamp);
        } else {
            assert(c.pastBlockTime() == oldBlockTime && address(c).balance == oldBalance);
        }
    }

    receive() external payable {}
}

