    constructor(C _c) { c = _c; }

    function run(uint preTime, uint amount, uint blkDelta) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        // A valid timestamp for the fallback: strictly greater than zero,
        // over 100 seconds in the future, and fitting in uint64 for a realistic block time.
        require(preTime > 0 && preTime < type(uint64).max);
        require(blkDelta > 0 && blkDelta < 100 years);

        uint t = block.timestamp + preTime + blkDelta;
        require(t > preTime);

        // Need c's pastBlockTime to be readable (getter call on c is view).
        require(preTime > c.pastBlockTime());

        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(address(c).balance == beforeBalance);
        } else {
            if (block.number % 15 == 0) {
                assert(address(c).balance == 0);
            } else {
                assert(address(c).balance == beforeBalance + amount);
            }
        }
    }
}

